      "objective": "Synthesize findings into actionable recommendations for students and teachers regarding which question types and topics to prioritize based on historical patterns."
    },
    {
      "section_id": "conclusions",
      "title": "Conclusions & Limitations",
      "objective": "Summarize key findings and note any data limitations such as missing years, supplementary vs. annual paper distinctions, or encoding considerations."
    }
